import ldap
import csv

def authenticate_user(username, password):
    """Authenticate user against LDAP using provided credentials."""
    try:
        conn = ldap.initialize('ldap://internal-ldap.company.local')
        conn.simple_bind_s(username, password)
        conn.unbind_s()
        return True
    except ldap.INVALID_CREDENTIALS:
        return False
    except ldap.SERVER_DOWN:
        return False

def process_credentials_file(csv_path):
    """Read CSV and authenticate each user."""
    results = []
    with open(csv_path, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            username = row['username']
            password = row['password']
            is_valid = authenticate_user(username, password)
            results.append({
                'username': username,
                'authenticated': is_valid
            })
    return results

if __name__ == '__main__':
    creds = process_credentials_file('users.csv')
    for result in creds:
        print(f"{result['username']}: {result['authenticated']}")
